{"code": "# [EDIT REGION] mission controller - modify ONLY this block\n# ===========================================================================\n\nimport math\nimport numpy as np\n\ndef _wrap_angle(a):\n    return math.atan2(math.sin(a), math.cos(a))\n\ndef _clamp(v, lo, hi):\n    return max(lo, min(hi, v))\n\n_BLOCK_START = None\n\ndef _future_crossing_ahead(pose, objs, lookahead=5.0, safety=0.5, t_pred=2.0):\n    \"\"\"Predict if any moving object will intersect the robot's forward line\n    segment of length `lookahead` within `t_pred` seconds.\n    \"\"\"\n    x, y, yaw = pose\n    # end of lookahead segment\n    seg_end = (x + math.cos(yaw) * lookahead, y + math.sin(yaw) * lookahead)\n    lx, ly = seg_end[0] - x, seg_end[1] - y\n    seg_len2 = lx * lx + ly * ly\n    if seg_len2 == 0:\n        return False\n    for o in objs:\n        if not o[\"vel_ok\"]:\n            continue\n        ox = o[\"x\"] + o[\"vx\"] * t_pred\n        oy = o[\"y\"] + o[\"vy\"] * t_pred\n        # projection onto segment\n        t = ((ox - x) * lx + (oy - y) * ly) / seg_len2\n        t = max(0.0, min(1.0, t))\n        cx, cy = x + t * lx, y + t * ly\n        if math.hypot(ox - cx, oy - cy) < safety:\n            return True\n    return False\n\n\ndef controller(t, pose, env):\n    x, y, yaw = pose\n\n    # ---------------------------------------------------------------\n    # 1) Goal handling \u2013 alignment & final stop\n    # ---------------------------------------------------------------\n    d_goal = math.hypot(GOAL[0] - x, GOAL[1] - y)\n    e_yaw = _wrap_angle(GOAL[2] - yaw)\n    if d_goal <= 0.5:\n        if abs(e_yaw) > 0.15:\n            v, w, info = choose_command(0.0, _clamp(1.5 * e_yaw, -0.4, 0.4), GOAL[:2])\n            return v, w, False\n        else:\n            v, w, info = choose_command(0.0, 0.0, GOAL[:2])\n            done = (v == 0.0 and w == 0.0)\n            return v, w, done\n\n    # ---------------------------------------------------------------\n    # 2) Predict crossing of moving objects ahead and wait if needed\n    # ---------------------------------------------------------------\n    objs = observed_objects()\n    if _future_crossing_ahead(pose, objs, lookahead=5.0, safety=0.5, t_pred=2.0):\n        # back up a little to stay clear of the line\n        v, w, info = choose_command(-0.2, 0.0, (GOAL[0], GOAL[1]))\n        return v, w, False\n\n    # ---------------------------------------------------------------\n    # 3) Normal navigation towards the goal\n    # ---------------------------------------------------------------\n    tx, ty = GOAL[0], GOAL[1]\n    dist = math.hypot(tx - x, ty - y)\n    e = _wrap_angle(math.atan2(ty - y, tx - x) - yaw)\n\n    if abs(e) > 0.35:\n        v_follow = 0.0\n        w_follow = _clamp(1.5 * e, -0.4, 0.4)\n    else:\n        v_follow = min(0.3, 0.5 * dist + 0.1)\n        w_follow = _clamp(1.5 * e, -0.4, 0.4)\n\n    v, w, info = choose_command(v_follow, w_follow, (tx, ty))\n\n    # ---------------------------------------------------------------\n    # 4) If chooser returns stop, rotate left until forward becomes safe\n    # ---------------------------------------------------------------\n    if info.get('chosen') == 'stop' and v == 0.0 and w == 0.0:\n        v, w, info = choose_command(0.0, 0.4, (tx, ty))\n        global _BLOCK_START\n        if not (info.get('chosen') == 'stop' and v == 0.0 and w == 0.0):\n            _BLOCK_START = None\n    else:\n        _BLOCK_START = None\n\n    return v, w, False\n\n# ========================= [END EDIT REGION] ==============================="}
